args.old_string:
get(key) {
  const entry = entries.get(key)
  if (entry === undefined) return undefined
  entry.lastUsed = clock()
  return entry.value
},
set(key, value) {
  const now = clock()
  if (entries.size >= capacity && !entries.has(key)) {
    // evict one entry to make room
    const victim = [...entries.entries()].sort((a, b) => b[1].lastUsed - a[1].lastUsed)[0]
    entries.delete(victim[0])
  }
  entries.set(key, { value, expiresAt: now + ttlMs, lastUsed: now })
},

args.new_string:
get(key) {
  const entry = entries.get(key)
  if (entry === undefined) return undefined
  const now = clock()
  if (now > entry.expiresAt) {
    // expired: treat as a miss and drop the entry
    entries.delete(key)
    return undefined
  }
  entry.lastUsed = now
  // re-insert to mark the entry as most recently used
  entries.delete(key)
  entries.set(key, entry)
  return entry.value
},
set(key, value) {
  const now = clock()
  if (entries.has(key)) {
    // refresh in place: re-insert to mark the entry as most recently used
    entries.delete(key)
  } else if (entries.size >= capacity) {
    // evict the least-recently-used entry (first in insertion order)
    const oldest = entries.keys().next().value
    entries.delete(oldest)
  }
  entries.set(key, { value, expiresAt: now + ttlMs, lastUsed: now })
},

set(key, value) {
  store.set(key, value)
  cache.set(key, value)
},
